  'network.region.lead': { en: 'From local communities to regional hubs, discover where the SYC network is active across six regions.', zh: '从本地社区到区域枢纽，探索 SYC 网络活跃于六大区域的足迹。', fr: 'Des communautés locales aux pôles régionaux, découvrez où le réseau SYC est actif dans six régions.', ru: 'От местных сообществ до региональных центров — узнайте, где активна сеть SYC в шести регионах.', ja: '地域コミュニティから地域ハブまで、SYC ネットワークが六大地域で活動する場所を発見。', ko: '지역 커뮤니티부터 지역 허브까지, SYC 네트워크가 6개 지역에서 활동하는 곳을 발견하세요.' },
  'network.teams.kicker': { en: 'The people behind the network', zh: '网络背后的人', fr: 'Les personnes derrière le réseau', ru: 'Люди за сетью', ja: 'ネットワークを支える人々', ko: '네트워크 뒤의 사람들' },
  'network.teams.title': { en: 'Our Youth Teams Around the World', zh: '世界各地的青年团队', fr: 'Nos équipes de jeunes dans le monde', ru: 'Наши молодёжные команды по всему миру', ja: '世界の青年チーム', ko: '전 세계 청년 팀' },
  'network.teams.lead': { en: 'Illustrative sample profiles behind the network — a preview of how representatives and leaders connect communities across regions.', zh: '网络背后的示例成员档案——预览代表与领袖如何跨越地区连接社区。', fr: 'Des profils d’exemple illustratifs derrière le réseau — un aperçu de la façon dont représentants et leaders relient les communautés entre les régions.', ru: 'Иллюстративные примеры профилей за сетью — предварительный взгляд на то, как представители и лидеры объединяют сообщества между регионами.', ja: 'ネットワークを支える例示プロフィール——代表とリーダーが地域を越えてコミュニティをつなぐ様子のプレビュー。', ko: '네트워크 뒤의 예시 프로필 — 대표와 리더가 지역을 넘어 커뮤니티를 연결하는 방식의 미리보기.' },
